-- Phase 73: controlled recovery records, not in-app database restore/delete.
create table public.rental_recovery_runs(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),runbook_key text not null check(runbook_key in('reconcile','import_replay','job_replay','integration_outage','deployment_check')),status text not null default 'planned' check(status in('planned','running','completed','failed','cancelled')),idempotency_key text not null,requested_by uuid not null references auth.users(id),result jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),completed_at timestamptz,unique(organisation_id,idempotency_key));
create index rental_recovery_runs_org_status_idx on public.rental_recovery_runs(organisation_id,status,created_at desc);create index rental_recovery_runs_requested_by_idx on public.rental_recovery_runs(requested_by);alter table public.rental_recovery_runs enable row level security;create policy "rental_recovery_runs_manager_read" on public.rental_recovery_runs for select to authenticated using(public.rental_financial_manager_authorized(organisation_id));
create or replace function public.rental_start_recovery_run(p_org uuid,p_runbook_key text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$ declare v_id uuid;begin if auth.uid() is null or not public.rental_financial_manager_authorized(p_org) or p_runbook_key not in('reconcile','import_replay','job_replay','integration_outage','deployment_check') or length(btrim(coalesce(p_idempotency_key,'')))<8 then raise exception 'Invalid recovery run';end if;insert into public.rental_recovery_runs(organisation_id,runbook_key,idempotency_key,requested_by,result)values(p_org,p_runbook_key,btrim(p_idempotency_key),auth.uid(),jsonb_build_object('destructive_restore',false,'next_step','Run approved operational runbook outside the browser.'))on conflict(organisation_id,idempotency_key)do update set idempotency_key=excluded.idempotency_key returning id into v_id;return jsonb_build_object('run_id',v_id,'status','planned');end $$;
create or replace function public.rental_get_recovery_health(p_org uuid)returns jsonb language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not public.rental_financial_manager_authorized(p_org)then raise exception 'Not authorized';end if;return jsonb_build_object('open_recovery_runs',(select count(*)from public.rental_recovery_runs where organisation_id=p_org and status in('planned','running')),'recent_runs',coalesce((select jsonb_agg(to_jsonb(x)order by x.created_at desc)from(select * from public.rental_recovery_runs where organisation_id=p_org order by created_at desc limit 20)x),'[]'::jsonb),'restore_notice','Backups and restores require the approved Supabase operational runbook.');end $$;
revoke all on function public.rental_start_recovery_run(uuid,text,text)from public,anon;revoke all on function public.rental_get_recovery_health(uuid)from public,anon;grant execute on function public.rental_start_recovery_run(uuid,text,text)to authenticated;grant execute on function public.rental_get_recovery_health(uuid)to authenticated;
